def transform(grid):
    from collections import Counter, deque

    rows, cols = len(grid), len(grid[0])

    counts = Counter()
    for row in grid:
        counts.update(row)
    bg = max(counts, key=counts.get)

    non_bg = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg:
                non_bg.append((r, c))

    visited = set()
    components = []

    for r, c in non_bg:
        if (r, c) in visited:
            continue

        q = deque([(r, c)])
        visited.add((r, c))
        comp = []

        while q:
            curr = q.popleft()
            comp.append(curr)
            cr, cc = curr
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        if (nr, nc) in non_bg and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            q.append((nr, nc))
        components.append(comp)

    sorted_comps = sorted(components, key=len, reverse=True)
    if not sorted_comps or not sorted_comps[0]:
        return grid

    template_comp = sorted_comps[0]

    r_sum = sum(p[0] for p in template_comp)
    c_sum = sum(p[1] for p in template_comp)
    center_r = r_sum / len(template_comp)
    center_c = c_sum / len(template_comp)

    result = [row[:] for row in grid]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == bg:
                continue
            if (r, c) not in template_comp:
                for tr, tc in template_comp:
                    nr = int(r + tr - center_r)
                    nc = int(c + tc - center_c)
                    if 0 <= nr < rows and 0 <= nc < cols:
                        result[nr][nc] = grid[tr][tc]

    return result
